import React, { useState } from 'react';
import { createEvent } from '../api';

const EventForm = ({ onEventAdded }) => {
  const [form, setForm] = useState({
    title: '',
    description: '',
    location: '',
    startTime: '',
    endTime: '',
  });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.title || !form.startTime || !form.endTime) {
      alert('Please fill title, start and end time');
      return;
    }
    try {
      await createEvent(form);
      setForm({ title: '', description: '', location: '', startTime: '', endTime: '' });
      onEventAdded(); // refresh event list
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <h2>Add Event</h2>
      <input type="text" name="title" placeholder="Title" value={form.title} onChange={handleChange} required />
      <input type="text" name="description" placeholder="Description" value={form.description} onChange={handleChange} />
      <input type="text" name="location" placeholder="Location" value={form.location} onChange={handleChange} />
      <input type="datetime-local" name="startTime" value={form.startTime} onChange={handleChange} required />
      <input type="datetime-local" name="endTime" value={form.endTime} onChange={handleChange} required />
      <button type="submit">Add Event</button>
    </form>
  );
};

export default EventForm;
